86	static void copy_flash(uint32_t size, SPI_TypeDef *spi) {
87		/* First, erase internal flash */
88		/* disable caches */
89		__HAL_FLASH_INSTRUCTION_CACHE_DISABLE();
90		__HAL_FLASH_DATA_CACHE_DISABLE();
91		/* Erase FLASH */
