95		SET_BIT(FLASH->CR, FLASH_CR_STRT);
96		// Wait for operation to finish
97		while (FLASH->SR & FLASH_SR_BSY)
98		;
99		// Clear bank1 erase request
100		CLEAR_BIT(FLASH->CR, (FLASH_CR_MER1));
101	
102		/* The complete FLASH has been erased. Copy the external FLASH memory
103		 * content into the internal MCU flash */
104		uint32_t written = 0;
105	
106		// Enable FIFO notifications for 8 bit
107		SET_BIT(spi->CR2, SPI_RXFIFO_THRESHOLD);
108	
109		/* Enable FLASH write */
110		FLASH->CR |= FLASH_CR_PG;
111		uint32_t *to = (uint32_t*) 0x8000000;
112		while (written < size) {
113			uint8_t buf[8];
114			// Get 64bit from external flash
115			for(uint8_t i=0;i<8;i++) {
116				// wait for SPI ready to transmit dummy data
117				while(!(spi->SR & SPI_FLAG_TXE));
118				// send dummy byte
119				*(__IO uint8_t *)&spi->DR = 0x00;
120				// wait for received byte to be ready
121				while(!(spi->SR & SPI_FLAG_RXNE));
122				// get received byte
123				buf[i] = *(__IO uint8_t *)&spi->DR;
124			}
125			// program received data into flash
126			*(__IO uint32_t*) to++ = *(uint32_t*)&buf[0];
127			__ISB();
128			*(__IO uint32_t*) to++ = *(uint32_t*)&buf[4];
129			/* Wait for it to finish */
130			while (FLASH->SR & FLASH_SR_BSY)
131				;
