133			uint32_t error = (FLASH->SR & FLASH_FLAG_SR_ERRORS);
134			error |= (FLASH->ECCR & FLASH_FLAG_ECCD);
135			if (error != 0u) {
136				/* Clear error programming flags */
137				__HAL_FLASH_CLEAR_FLAG(error);
138			}
139			/* Check FLASH End of Operation flag  */
140			if (__HAL_FLASH_GET_FLAG(FLASH_FLAG_EOP)) {
141				/* Clear FLASH End of Operation pending bit */
142				__HAL_FLASH_CLEAR_FLAG(FLASH_FLAG_EOP);
