37	bool FirmwareUpdateDialog::FirmwareUpdate(LibreVNADriver *dev, QString file)
38	{
39	    FirmwareUpdateDialog d(dev);
40	    d.deleteAfterUpdate = false;
41	    d.ui->lFile->setText(file);
42	    d.reloadFile();
43	    d.on_bStart_clicked();
44	    d.show();
45	    QEventLoop loop;
46	    while(d.state != State::Idle) {
47	        loop.processEvents(QEventLoop::AllEvents, 100);
48	    }
