52	void FirmwareUpdateDialog::on_bFile_clicked()
53	{
54	    ui->bStart->setEnabled(false);
55	    auto filename = QFileDialog::getOpenFileName(nullptr, "Open firmware file", Preferences::getInstance().UISettings.Paths.firmware, "Firmware file (*.vnafw)", nullptr, Preferences::QFileDialogOptions());
56	    if (filename.length() > 0) {
57	        Preferences::getInstance().UISettings.Paths.firmware = QFileInfo(filename).path();
58	        ui->lFile->setText(filename);
59	        reloadFile();
60	    }
61	}
