70	void FirmwareUpdateDialog::on_bStart_clicked()
71	{
72	    success = false;
73	    ui->status->clear();
74	    ui->bStart->setEnabled(false);
75	    if(!file->isOpen()) {
76	        if(!file->open(QIODevice::ReadOnly)) {
77	            abortWithError("Unable to open file");
78	            return;
79	        }
80	    }
81	    file->seek(0);
82	    addStatus("Evaluating file...");
83	    if(file->size() % PacketConstants::FW_CHUNK_SIZE != 0) {
84	        abortWithError("Invalid file size");
85	        return;
86	    }
87	    char header[24];
88	    file->read(header, sizeof(header));
89	    if(strncmp(header, dev->getFirmwareMagicString().toStdString().c_str(), 4)) {
90	        // might be a firmware file for a wrong LibreVNA
91	        if(dev->getProtocolVersion() == Protocol::Version) {
92	            // we are talking to a LibreVNA with the correct protocol, this is definitely the wrong firmware file
93	            abortWithError("Invalid magic header constant");
94	            return;
95	        } else {
96	            // we might be talking to the correct hardware but with the wrong protocol version (which might result
97	            // in the magic string check falsely failing. Process after user confirmation
98	            auto confirm = InformationBox::AskQuestion("Continue?", "The firmware magic header constant does not match the expected"
99	                                                     " value for your LibreVNA. Either this is the wrong firmware file"
100	                                                     " or the hardware ID of your LibreVNA was read incorrectly. This"
101	                                                     " can happen if the LibreVNA uses a different protocol version than"
102	                                                     " what it expected by the GUI. Do you want to continue with the firmware update?", true);
103	            if(!confirm) {
104	                abortWithError("Aborted by user");
105	                return;
106	            }
107	        }
108	
109	    }
110	    file->seek(0);
111	    state = State::ErasingFLASH;
112	    disconnect(dev, nullptr, this, nullptr);
113	    connect(dev, &LibreVNADriver::receivedAnswer, this, [=](const LibreVNADriver::TransmissionResult &res) {
114	        if(res == LibreVNADriver::TransmissionResult::Ack) {
115	            receivedAck();
116	        } else if(res == LibreVNADriver::TransmissionResult::Nack) {
117	            receivedNack();
118	        }
119	    }, Qt::QueuedConnection);
120	    addStatus("Erasing device memory...");
121	    dev->sendWithoutPayload(Protocol::PacketType::ClearFlash);
122	    timer.setSingleShot(true);
123	    timer.start(20000);
124	}
