126	void FirmwareUpdateDialog::addStatus(QString line)
127	{
128	    ui->status->appendPlainText(line);
129	}
130	
131	void FirmwareUpdateDialog::abortWithError(QString error)
132	{
133	    timer.stop();
134	
135	    QTextCharFormat tf;
136	    tf = ui->status->currentCharFormat();
137	    tf.setForeground(QBrush(Qt::red));
138	    ui->status->setCurrentCharFormat(tf);
139	    ui->status->appendPlainText(error);
140	    tf.setForeground(QBrush(Qt::black));
141	    ui->status->setCurrentCharFormat(tf);
142	    ui->bStart->setEnabled(true);
143	    success = false;
144	    state = State::Idle;
145	}
146	
147	void FirmwareUpdateDialog::timerCallback()
148	{
149	    switch(state) {
150	    case State::WaitingForReboot: {
151	        // Currently waiting for the reboot, check device list
152	        auto devices = dev->GetAvailableDevices();
153	        if(devices.find(serialnumber) != devices.end()) {
154	            // the device rebooted and is available again
155	            addStatus("...device enumerated, update complete");
156	            state = State::WaitBeforeInitializing;
157	            timer.start(3000);
158	        }
159	    }
160	        break;
161	    case State::WaitBeforeInitializing:
162	        // Device had enough time to initialize, indicate that rebooted device is ready
163	        timer.stop();
164	        if(dev->connectDevice(serialnumber)) {
165	            success = true;
166	            if(deleteAfterUpdate) {
167	                delete this;
168	            }
169	        } else {
170	            abortWithError("Failed to connect to updated device");
171	        }
172	        state = State::Idle;
173	        break;
174	    default:
175	        abortWithError("Response timed out");
176	        break;
177	    }
178	}
179	
180	void FirmwareUpdateDialog::receivedAck()
181	{
182	    switch(state) {
183	    case State::Idle:
184	        // no firmware update in progress, ignore
185	        break;
186	    case State::ErasingFLASH:
187	        // FLASH erased, begin transferring firmware
188	        state = State::TransferringData;
189	        transferredBytes = 0;
190	        addStatus("Transferring firmware...");
191	        sendNextFirmwareChunk();
192	        timer.start(1000);
193	        break;
194	    case State::TransferringData:
195	        transferredBytes += PacketConstants::FW_CHUNK_SIZE;
196	        ui->progress->setValue(100 * transferredBytes / file->size());
197	        if(transferredBytes >= file->size()) {
198	            // complete file transferred
199	            addStatus("Triggering device update...");
200	            state = State::TriggeringUpdate;
201	            dev->sendWithoutPayload(Protocol::PacketType::PerformFirmwareUpdate);
202	            timer.start(5000);
203	        } else {
204	            sendNextFirmwareChunk();
205	            timer.start(1000);
206	        }
207	        break;
208	    case State::TriggeringUpdate:
209	        addStatus("Rebooting device...");
210	        serialnumber = dev->getSerial();
211	        dev->disconnectDevice();
212	        state = State::WaitingForReboot;
213	        timer.setSingleShot(false);
214	        timer.start(2000);
215	        break;
216	    default:
217	        break;
218	    }
219	}
220	
221	void FirmwareUpdateDialog::receivedNack()
222	{
223	    switch(state) {
224	    case State::ErasingFLASH:
225	        abortWithError("Nack received, device does not support firmware update");
226	        break;
227	    default:
228	        abortWithError("Nack received, something went wrong");
229	        break;
230	    }
231	
232	}
233	
234	void FirmwareUpdateDialog::sendNextFirmwareChunk()
235	{
236	    Protocol::PacketInfo p = {};
237	    p.type = Protocol::PacketType::FirmwarePacket;
238	    p.firmware.address = transferredBytes;
239	    file->read((char*) &p.firmware.data, PacketConstants::FW_CHUNK_SIZE);
240	    dev->SendPacket(p);
241	}
