	static constexpr uint8_t PCKT_EXCL_PAYLOAD_LEN = PCKT_COMBINED_HEADER_LEN + PCKT_CRC_LEN;  // combined length of all packet fields, excluding payload

	/////////////////////////////////////////////////////////////
	//  Payload content

