	static constexpr uint16_t FW_CHUNK_SIZE = 256;

	//  VNADataPoint payload fields in bytes
	static constexpr uint8_t DPNT_FREQ_LEN = 8;
	static constexpr uint8_t DPNT_POW_LVL_LEN = 2;
